// Кейс: .qa/tests/camera-aim/CAM-004.md · план: .qa/e2e-app/specs/app.md (1.50)
// Бледная/светлая («תכלת») вода с брызгами проходит сама: красной зоны и «לא זוהו מים…» нет, «בהירים מהרגיל» нет,
// без «זו הבריכה שלי»; галочка «כל שטח המים נראה…» → «המשך» активна. Цвет точек (зелёный) — визуально по скриншоту, вручную.
// РУЧНАЯ СЦЕНА (требует подготовки): камера iPhone смотрит на экран Mac (Safari на весь экран, яркость фиксированная, Chrome пользователя
// не перекрывает), на нём на весь экран видео .qa/media/girl-swimming-oblique.mp4; 4 точки — вокруг воды (автоконтур или руками).
// BANCI_SCENE=pool-pale (иначе пропуск). Мониторинг НЕ запускается («המשך» не нажимается).
import { by, assert, skip, checkedFromValue } from '../../lib/appium.mjs';
import { openCameraStep, waitEnabled } from '../../lib/banci.mjs';

export const name = 'Шаг 2, бледная вода (видео бассейна «תכלת»): без «לא זוהו מים»/«בהירים מהרגיל»/«זו הבריכה שלי», галочка → «המשך» активна (ручная сцена BANCI_SCENE=pool-pale) #ab4270 @iphone @app @prod-safe';

export default async function (app) {
  if (!['pool-pale', 'water'].includes(process.env.BANCI_SCENE)) skip('ручная сцена: на Mac на весь экран .qa/media/girl-swimming-oblique.mp4, камера iPhone на экран, 4 точки вокруг воды → BANCI_SCENE=pool-pale');

  const water = await openCameraStep(app);
  assert(!(await app.exists(by.contains('זו הבריכה שלי'))), 'нет галочки «זו הבריכה שלי» (OTA c38476a1 не загрузился?)');
  if (checkedFromValue(await water.attr('value')) !== true) await water.click();
  const next = await app.waitFor(by.exact('המשך', 'Button'), { what: '«המשך» на шаге 2' });
  await waitEnabled(next, true, { timeout: 20000, what: '«המשך» на бледной воде с галочкой (если серая — смотреть подсказку на экране: правило «светлой воды» циан 170–211°, насыщенность ≥ 0.10)' });
  assert(!(await app.exists(by.contains('לא זוהו מים באזור שסומן'))), 'при воде в кадре нет «לא זוהו מים באזור שסומן…» (проверить сцену: видео на весь экран Mac)');
  assert(!(await app.exists(by.contains('בהירים מהרגיל'))), 'нет «בהירים מהרגיל»');
  await app.screenshot('ab4270-pale-pool-green-continue-active');
  await app.restart();
}
